# Generated by tilefish (tilefish.col2im1d) for f32, kernel 7, stride 2, dilation 1, padding 3 before and 3 after, output padding 1, channel order, ncl layout, a bias, 80 channels. Do not edit.
# y[n, c, t] = +0.0 + cols[n, i, c * 7 + j] + ... over every (i, j) with t + 3 = i * 2 + j, in ascending i (descending j), one f32 add each, then + bias[c]; rounded once to f32 at the store. i64 offsets.
import triton
import triton.language as tl


@triton.jit
def tf_col2im1d_f32_k7_s2_d1_p3x3_op1_channel_ncl_bias_c80(
    cols,
    bias,
    y,
    Li,
    Lo,
    cols_s0,
    cols_s1,
    cols_s2,
    BLOCK: tl.constexpr,
):
    t = tl.program_id(0)
    n = tl.program_id(1).to(tl.int64)
    src = cols + n * cols_s0
    for c0 in range(0, 80, BLOCK):
        c = c0 + tl.arange(0, BLOCK)
        cm = c < 80
        acc = tl.zeros([BLOCK], dtype=tl.float32)
        for r in tl.static_range(7):
            j = 6 - r  # descending taps: ascending input positions
            q = t + 3 - j
            i = q // 2
            ok = (q >= 0) & (q % 2 == 0) & (i < Li)
            v = tl.load(src + i * cols_s1 + (c * 7 + j) * cols_s2, mask=cm & ok, other=0.0)
            acc = acc + v
        acc = acc + tl.load(bias + c, mask=cm, other=0.0)
        tl.store(y + (n * 80 + c) * Lo + t, acc, mask=cm)
